#include "stdlib/blas/ext/base/cediff.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/strided/base/stride2offset.h"
#include "stdlib/blas/base/ccopy.h"
#include "stdlib/blas/base/shared.h"

/**
* Calculates the differences between consecutive elements of a single-precision complex floating-point strided array.
*
* @param N          number of indexed elements
* @param X          input array
* @param strideX    stride length for X
* @param N1         number of indexed elements to prepend
* @param Prepend    prepend array
* @param strideP    stride length for Prepend
* @param N2         number of indexed elements to append
* @param Append     append array
* @param strideA    stride length for Append
* @param Out        output array
* @param strideOut  stride length for Out
*/
void API_SUFFIX(stdlib_strided_cediff)( const CBLAS_INT N, const stdlib_complex64_t *X, const CBLAS_INT strideX, const CBLAS_INT N1, const stdlib_complex64_t *Prepend, const CBLAS_INT strideP, const CBLAS_INT N2, const stdlib_complex64_t *Append, const CBLAS_INT strideA, stdlib_complex64_t *Out, const CBLAS_INT strideOut ) {
	const CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	const CBLAS_INT op = stdlib_strided_stride2offset( N1, strideP );
	const CBLAS_INT oa = stdlib_strided_stride2offset( N2, strideA );
	const CBLAS_INT oo = stdlib_strided_stride2offset( N+N1+N2-1, strideOut );
	API_SUFFIX(stdlib_strided_cediff_ndarray)( N, X, strideX, ox, N1, Prepend, strideP, op, N2, Append, strideA, oa, Out, strideOut, oo );
}

/**
* Calculates the differences between consecutive elements of a single-precision complex floating-point strided array using alternative indexing semantics.
*
* @param N          number of indexed elements
* @param X          input array
* @param strideX    stride length for X
* @param offsetX    starting index for X
* @param N1         number of indexed elements to prepend
* @param Prepend    prepend array
* @param strideP    stride length for Prepend
* @param offsetP    starting index for Prepend
* @param N2         number of indexed elements to append
* @param Append     append array
* @param strideA    stride length for Append
* @param offsetA    starting index for Append
* @param Out        output array
* @param strideOut  stride length for Out
* @param offsetOut  starting index for Out
*/
void API_SUFFIX(stdlib_strided_cediff_ndarray)( const CBLAS_INT N, const stdlib_complex64_t *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const CBLAS_INT N1, const stdlib_complex64_t *Prepend, const CBLAS_INT strideP, const CBLAS_INT offsetP, const CBLAS_INT N2, const stdlib_complex64_t *Append, const CBLAS_INT strideA, const CBLAS_INT offsetA, stdlib_complex64_t *Out, const CBLAS_INT strideOut, const CBLAS_INT offsetOut ) {
	const float *xv = (float *)X;
	float *ov = (float *)Out;
	CBLAS_INT total;
	CBLAS_INT sx;
	CBLAS_INT so;
	CBLAS_INT ix;
	CBLAS_INT io;
	CBLAS_INT fo;
	CBLAS_INT i;
	float rprev;
	float iprev;
	float rcurr;
	float icurr;

	total = N + N1 + N2;
	if ( total <= 1 ) {
		return;
	}
	// Copy `Prepend` into output array:
	API_SUFFIX(c_ccopy_ndarray)( N1, (const void *)Prepend, strideP, offsetP, (void *)Out, strideOut, offsetOut );

	// Adjust the strides for the interleaved layout:
	sx = strideX * 2;
	so = strideOut * 2;

	// Compute differences of the input array:
	ix = offsetX * 2;
	io = offsetOut + ( N1 * strideOut );
	fo = io * 2;
	if ( N > 0 ) {
		rprev = xv[ ix ];
		iprev = xv[ ix+1 ];
		for ( i = 1; i < N; i++ ) {
			ix += sx;
			rcurr = xv[ ix ];
			icurr = xv[ ix+1 ];
			ov[ fo ] = rcurr - rprev;
			ov[ fo+1 ] = icurr - iprev;
			rprev = rcurr;
			iprev = icurr;
			io += strideOut;
			fo += so;
		}
	}
	// Copy `Append` into output array:
	API_SUFFIX(c_ccopy_ndarray)( N2, (const void *)Append, strideA, offsetA, (void *)Out, strideOut, io );

	return;
}
